   155	function slotReclaimable(occupant: SlotOccupant, file: string, now: number, staleMs: number): boolean {
   156	  if (occupant.state === 'missing') return true;
   157	  if (occupant.state === 'valid') {
   158	    const isolated = occupant.meta.providerProcessGroupIsolated === true;
   159	    const providerPgid = ownNumber(occupant.meta, 'providerPgid');
   160	    // Once the admission has transferred to an isolated provider group, the
   161	    // group—not the supervising worker—is the capacity owner. A crashed worker
   162	    // may leave children alive, so reclaim only after the exact PGID disappears.
   163	    if (isolated && providerPgid !== null && processGroupAlive(providerPgid)) return false;
   164	    return !pidAlive(occupant.pid);
   165	  }
   166	  try {
   167	    const ageMs = now - statSync(file).mtimeMs;
   168	    return !Number.isFinite(ageMs) || ageMs > staleMs;
   169	  } catch {
   170	    // Fail closed: an existing slot we cannot stat still occupies capacity.
   171	    return false;
   172	  }
   173	}
