    87	/**
    88	 * Narrow child-process surface for launcher-failure cleanup. It deliberately
    89	 * carries no PGID: before the worker has published a verified process identity,
    90	 * descriptor-delivery failure may only target the direct child.
    91	 */
    92	export interface ManagedHostRunLaunchedWorkerHandle {
    93	  pid?: number;
    94	  exitCode: number | null;
    95	  signalCode: NodeJS.Signals | null;
