   100	/**
   101	 * Best-effort direct-child cleanup before a worker has returned a durable,
   102	 * fingerprint-bound process identity. Do not infer that `pid` is an isolated
   103	 * process group: a negative-PGID signal here could target a recycled or
   104	 * unrelated group. The launch failure remains replacement-unsafe at the
   105	 * submitter boundary even if this direct-child reap appears to succeed.
   106	 */
   107	export async function reapUnidentifiedManagedHostRunWorker(
   108	  child: ManagedHostRunLaunchedWorkerHandle,
   109	  wait: (ms: number) => Promise<void> = sleep,
   110	): Promise<{ directKillSent: boolean; reaped: boolean }> {
   111	  let directKillSent = false;
   112	  if (child.pid && child.pid > 1) {
   113	    try {
   114	      directKillSent = child.kill('SIGKILL') !== false;
   115	    } catch {
   116	      // The child may already have exited; retain a replacement-unsafe launch failure.
   117	    }
   118	  }
   119	  let reaped = child.exitCode !== null || child.signalCode !== null;
   120	  if (!reaped) {
   121	    await Promise.race([
   122	      new Promise<void>(resolveClose => {
   123	        child.once('close', resolveClose);
   124	        child.once('error', resolveClose);
   125	      }),
   126	      wait(1_000),
   127	    ]);
   128	    reaped = child.exitCode !== null || child.signalCode !== null;
   129	  }
   130	  return { directKillSent, reaped };
   131	}
