    61	/**
    62	 * Metadata from a managed receipt importer is the sole permitted HEAD advance
    63	 * between the signed review run and receipt admission. The check is deliberately
    64	 * mechanical: ancestry, exact command-owned subject, and exact story-local
    65	 * changed paths must all hold for every intervening commit.
    66	 */
    67	function hasOnlyManagedReviewImporterCommits(args: {
    68	  gitCwd: string;
    69	  storyId: string;
    70	  reviewedHeadHash: string;
    71	  liveHeadHash: string;
    72	}): boolean {
    73	  if (args.reviewedHeadHash === args.liveHeadHash) return true;
    74	  try {
    75	    execFileSync('git', ['merge-base', '--is-ancestor', args.reviewedHeadHash, args.liveHeadHash], {
    76	      cwd: args.gitCwd,
    77	      stdio: ['ignore', 'ignore', 'ignore'],
    78	    });
    79	    const commits = execFileSync('git', ['rev-list', '--reverse', `${args.reviewedHeadHash}..${args.liveHeadHash}`], {
    80	      cwd: args.gitCwd,
    81	      encoding: 'utf8',
    82	      stdio: ['ignore', 'pipe', 'pipe'],
    83	    }).trim().split('\n').filter(Boolean);
    84	    if (commits.length === 0) return false;
    85	    const expectedSubject = `lattice: record ${args.storyId} managed_review_evidence_import metadata`;
    86	    return commits.every(commit => {
    87	      const subject = execFileSync('git', ['show', '-s', '--format=%s', commit], {
    88	        cwd: args.gitCwd,
    89	        encoding: 'utf8',
    90	        stdio: ['ignore', 'pipe', 'pipe'],
    91	      }).trim();
    92	      if (subject !== expectedSubject) return false;
    93	      const files = execFileSync('git', ['diff-tree', '--no-commit-id', '--name-only', '-r', commit], {
    94	        cwd: args.gitCwd,
    95	        encoding: 'utf8',
    96	        stdio: ['ignore', 'pipe', 'pipe'],
    97	      }).trim().split('\n').filter(Boolean);
    98	      const names = new Set(files.map(file => file.split('/').at(-1)));
    99	      return files.length > 0
   100	        && files.every(file => file.includes(`/${args.storyId}/`))
   101	        && (names.has('review-passes.json') || names.has('findings.json'));
   102	    });
   103	  } catch {
   104	    return false;
   105	  }
   106	}
