   108	/**
   109	 * Canonical live binding rule for both receipt import and REVIEW consumption.
   110	 * Material/story-file freshness remains the Proof Admissibility predicate, but
   111	 * a same-material HEAD move is rejected unless every intervening commit is an
   112	 * exact managed-review importer metadata commit.
   113	 */
   114	export function verifyManagedReviewLiveBinding(args: {
   115	  gitCwd: string;
   116	  metadataRoot: string;
   117	  storyId: string;
   118	  expected: Pick<ManagedReviewExpectedBinding, 'headHash' | 'materialHash' | 'storyFilesHash'>;
   119	}): ManagedReviewLiveBindingVerification {
   120	  const liveHeadHash = currentGitHead(args.gitCwd);
   121	  if (!liveHeadHash) return { valid: false, reason: 'managed_review_live_head_unavailable' };
   122	  const liveMaterialHash = currentMaterialHash(args.gitCwd, 'HEAD', args.metadataRoot);
   123	  if (!liveMaterialHash || liveMaterialHash !== args.expected.materialHash) {
   124	    return {
   125	      valid: false,
   126	      reason: `managed_review_live_material_stale:reviewed=${args.expected.materialHash}:live=${liveMaterialHash ?? 'unavailable'}`,
   127	    };
   128	  }
   129	  if (!hasOnlyManagedReviewImporterCommits({
   130	    gitCwd: args.gitCwd,
   131	    storyId: args.storyId,
   132	    reviewedHeadHash: args.expected.headHash,
   133	    liveHeadHash,
   134	  })) {
   135	    return {
   136	      valid: false,
   137	      reason: `managed_review_live_head_lineage_invalid:reviewed=${args.expected.headHash}:live=${liveHeadHash}`,
   138	    };
   139	  }
   140	  return { valid: true, reason: 'managed_review_live_binding_current' };
   141	}
