   231	export function resolveManagedReviewerBasePrompt(root: string, run: ReviewRun): string {
   232	  if (run.assembledPrompt) return run.assembledPrompt;
   233	  // A no-envelope ReviewRun predates modular prompt assembly. Its signed
   234	  // promptHash therefore names the frozen legacy role body, regardless of a
   235	  // later rollout/template-mode change in the live project configuration.
   236	  // Reconstructing through that current mode turns valid historical evidence
   237	  // into apparent prompt drift; current envelope runs keep their strict exact
   238	  // assembled-prompt verification above.
   239	  const body = resolvePromptRoleBody(run.lane, {
   240	    version: PROMPT_ENVELOPE_ROLLOUT_VERSION,
   241	    roles: { [run.lane]: 'legacy-full-context' },
   242	  }).body;
   243	  if (rawSha256(body) !== run.promptHash) {
   244	    throw new Error('managed reviewer: legacy ReviewRun prompt hash does not match the canonical role body');
   245	  }
   246	  return body;
   247	}
