   249	/**
   250	 * Render the signed ReviewRun prompt for a managed provider without turning
   251	 * its canonical audit workspace into a provider execution instruction.
   252	 *
   253	 * `assembledPrompt` remains the signed, durable review context.  Formal
   254	 * managed-review providers instead receive this derived rendering and execute
   255	 * in the scratch cwd sealed by managed-host-run.  Native reviewer dispatch
   256	 * continues to receive the unmodified assembled prompt.
   257	 */
   258	export function renderManagedReviewerProviderPrompt(basePrompt: string, canonicalRoot: string): string {
   259	  const primaryWorktree = canonicalRoot.trim();
   260	  if (!primaryWorktree) return basePrompt;
   261	  return basePrompt
   262	    .split(/\r?\n/)
   263	    .filter(line => {
   264	      const trimmed = line.trim();
   265	      return !(trimmed.includes(primaryWorktree)
   266	        && /^working directory(?:\s*\(subagent must cd here\))?\s*:/i.test(trimmed));
   267	    })
   268	    .join('\n');
   269	}
