   271	function renderManagedReviewerCanonicalReportSnapshot(
   272	  statuses: readonly ManagedReviewCanonicalReportStatus[],
   273	): string[] {
   274	  const byCommand = new Map(statuses.map(status => [status.command, status]));
   275	  if (byCommand.size !== MANAGED_REVIEW_CANONICAL_REPORT_COMMANDS.length
   276	    || statuses.length !== MANAGED_REVIEW_CANONICAL_REPORT_COMMANDS.length
   277	    || MANAGED_REVIEW_CANONICAL_REPORT_COMMANDS.some(command => !byCommand.has(command))) {
   278	    throw new Error('managed reviewer: canonical report snapshot must contain each required command exactly once');
   279	  }
   280	  const validStatus = new Set(['pass', 'fail', 'inconclusive', 'missing', 'unavailable']);
   281	  const validCode = /^[A-Za-z0-9_.:-]{1,96}$/;
   282	  const rows = MANAGED_REVIEW_CANONICAL_REPORT_COMMANDS.map(command => {
   283	    const entry = byCommand.get(command)!;
   284	    if ((entry.availability !== 'available' && entry.availability !== 'unavailable')
   285	      || !validStatus.has(entry.status)
   286	      || (entry.blocking !== null && typeof entry.blocking !== 'boolean')
   287	      || !Array.isArray(entry.codes)) {
   288	      throw new Error(`managed reviewer: invalid canonical report snapshot entry for ${command}`);
   289	    }
   290	    const codes = entry.codes
   291	      .filter(code => typeof code === 'string' && validCode.test(code))
   292	      .slice(0, 12);
   293	    return `${command}: availability=${entry.availability}; status=${entry.status}; blocking=${entry.blocking ?? 'unknown'}; codes=${codes.join(',') || 'none'}`;
   294	  });
   295	  return [
   296	    '--- BEGIN CONTROLLER-FETCHED CANONICAL REPORT STATUS ---',
   297	    'These bounded read-only status projections were evaluated by the controller against the signed canonical review context before this provider launched.',
   298	    'This managed-only execution-boundary instruction overrides any earlier generic reviewer request to read these reports directly. Consume these entries directly. Do NOT invoke acceptance_topology_check, pre_review_check_read, acceptance_rollout_report_read, or acceptance_rollout_check from this scratch worktree.',
   299	    'An unavailable entry is an honest controller-evaluation limitation; report it if relevant and do not retry that CLI reader from the provider.',
   300	    ...rows,
   301	    '--- END CONTROLLER-FETCHED CANONICAL REPORT STATUS ---',
   302	  ];
   303	}
