   360	export function verifyManagedReviewEvidence(args: {
   361	  root: string;
   362	  storyId: string;
   363	  agent: string;
   364	  reviewRunId: string;
   365	  lane: string;
   366	  binding: ManagedReviewEvidenceBinding;
   367	  expected: ManagedReviewExpectedBinding;
   368	  evidence?: { kind: 'pass'; pass: ReviewPass } | { kind: 'finding'; finding: Finding };
   369	}): ManagedReviewEvidenceVerification {
   370	  let receipt: ManagedHostRunReceipt;
   371	  let proposal: ManagedReviewEvidenceProposal | null;
   372	  let runBinding: ReturnType<typeof readManagedHostRunBinding>;
   373	  try {
   374	    receipt = managedHostRunReceipt(args.root, args.binding.runId);
   375	    proposal = readManagedReviewEvidenceProposal(args.root, args.binding.runId);
   376	    runBinding = readManagedHostRunBinding(args.root, args.binding.runId);
   377	  } catch (error) {
   378	    // B-137a:F-107 — the artifact read failed (missing/corrupt receipt,
   379	    // proposal or run binding). The verdict stays fail-closed, but surface WHY
   380	    // instead of discarding it: without this, a corrupt-artifact refusal and a
   381	    // genuinely-absent-artifact refusal are indistinguishable to an operator.
   382	    const diagnostic = failedDiagnostic();
   383	    const cause = error instanceof Error ? error.message : String(error);
   384	    return {
   385	      valid: false,
   386	      reason: `${diagnostic.reasons.join(',')} (artifact read failed: ${cause})`,
   387	      diagnostic,
   388	      receipt: null,
   389	      proposal: null,
   390	    };
   391	  }
   392	  const terminalPath = join(managedHostRunDirectory(args.root, args.binding.runId), 'terminal.json');
   393	  const runDirectory = managedHostRunDirectory(args.root, args.binding.runId);
   394	  // B-137a:F-120 — these runtime-directory reads must share the SAME fail-closed
   395	  // guard as the artifact reads above. The F-107 fix wrapped only the receipt /
   396	  // proposal / run-binding reads, leaving terminal.json, evidence-proposal.json,
   397	  // spec.json, events.jsonl, result.json and the readdir unguarded: a partially
   398	  // written or pruned run directory (pruneExpiredManagedHostRuns can delete one
   399	  // that is later re-verified) made verification THROW instead of returning the
   400	  // intended diagnostic refusal, so an operator saw a stack trace rather than a
   401	  // reason code. Fail-closed is the contract for every read on this path.
   402	  let observedTerminalDigest: string;
   403	  let observedProposalDigest: string | null;
   404	  let proposalArtifacts: string[];
   405	  let observedSpecDigest: string;
   406	  let observedEventJournalDigest: string;
   407	  let observedResultDigest: string | null;
   408	  // B-137a:F-127 — archive-backed recover after terminal-retention GC
   409	  // (>= 90 days, and only via an explicit `doctor --repair`). The heavy run
   410	  // directory is deleted; `.lattice/runtime/host-run-receipts/<runId>.json`
   411	  // retains the sealed receipt, evidence-binding digest, binding projection,
   412	  // provider-authored proposal body, and import-seal pair. Heavy live-output
   413	  // and result provider text are not retained.
   414	  //
   415	  // The digests below are only ever compared against that same receipt's
   416	  // digests, so when the artifacts are legitimately reclaimed the archived
   417	  // receipt IS the authority; adopting its values preserves exactly the
   418	  // comparison that would otherwise have been made, and the archive is
   419	  // self-verifying (receiptId is recomputed over the archived payload). The
   420	  // proposal and import-seal pair are recovered by their archive-backed
   421	  // readers after digest/schema checks. While the directory exists the live
   422	  // files are read and compared exactly as before.
   423	  //
   424	  // Refuse-closed: pre-F-127 archives that lack the later capture fields,
   425	  // receipt/proposal/binding digest mismatches, archived-seal
   426	  // schemaVersion/runId/bindingDigest mismatches, and active/corrupt/one-shot
   427	  // runs (those are never GC'd).
   428	  const runDirectoryReclaimed = !existsSync(join(runDirectory, 'spec.json'))
   429	    && !existsSync(join(runDirectory, 'terminal.json'));
   430	  if (runDirectoryReclaimed) {
   431	    observedTerminalDigest = args.binding.terminalDigest;
   432	    observedProposalDigest = receipt.evidenceProposalDigest;
   433	    proposalArtifacts = receipt.evidenceProposalDigest ? ['evidence-proposal.json'] : [];
   434	    observedSpecDigest = receipt.specDigest;
   435	    observedEventJournalDigest = receipt.eventJournalDigest;
   436	    observedResultDigest = receipt.resultDigest;
   437	  } else try {
   438	    observedTerminalDigest = sha256(readFileSync(terminalPath, 'utf8'));
   439	    observedProposalDigest = proposal
   440	      ? sha256(readFileSync(join(runDirectory, 'evidence-proposal.json'), 'utf8'))
   441	      : null;
   442	    proposalArtifacts = readdirSync(runDirectory)
